const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a polygon for the Leipzig mining region (Neuseenland area)
  // This is a rough approximation of the lake district south of Leipzig.
  const geometry = ee.Geometry.Polygon(
    [[[12.33230635201292, 51.17149306029808],
      [12.33230635201292, 51.10991957017646],
      [12.569680375449764, 51.10991957017646],
      [12.569680375449764, 51.17149306029808],
      [12.33230635201292, 51.17149306029808]]]);

  const year1987 = '1987-04-01';
  const year1987End = '1987-04-30';
  const year2020 = '2020-04-01';
  const year2020End = '2020-04-30';

  // Cloud masking functions
  function maskL5Clouds(image) {
    const qa = image.select('pixel_qa');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask).select(['B2', 'B5'])
                .copyProperties(image, ['system:time_start']);
  }

  function maskS2Clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = (1 << 10);
    const cirrusBitMask = (1 << 11);
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).select(['B3', 'B11'])
                .copyProperties(image, ['system:time_start']);
  }

  // MNDWI calculation functions
  function calculateMNDWIL5(image) {
    // Green: B2, SWIR1: B5
    return image.normalizedDifference(['B2', 'B5']).rename('MNDWI');
  }

  function calculateMNDWIS2(image) {
    // Green: B3, SWIR1: B11
    return image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
  }

  // 2. Data Acquisition & Check

  // Landsat 5 for 1987
  let collection1987 = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
    .filterBounds(geometry)
    .filterDate(year1987, year1987End)
    .map(maskL5Clouds)
    .map(calculateMNDWIL5);

  const size1987 = await collection1987.size().getInfo();
  if (size1987 === 0) {
    console.log("No images found for April 1987 (Landsat 5).");
    console.log("C1");
    return;
  }
  const image1987 = collection1987.median();

  // Sentinel-2 for 2020
  let collection2020 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(geometry)
    .filterDate(year2020, year2020End)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Filter for less cloudy images
    .map(maskS2Clouds)
    .map(calculateMNDWIS2);

  const size2020 = await collection2020.size().getInfo();
  if (size2020 === 0) {
    console.log("No images found for April 2020 (Sentinel-2).");
    console.log("C1");
    return;
  }
  const image2020 = collection2020.median();

  // 3. Processing (Calculate water extent)
  // Threshold MNDWI to identify water (MNDWI > 0 typically)
  const water1987 = image1987.select('MNDWI').gt(0);
  const water2020 = image2020.select('MNDWI').gt(0);

  // Calculate pixel area for each image
  const pixelArea1987 = ee.Image.pixelArea().mask(water1987);
  const pixelArea2020 = ee.Image.pixelArea().mask(water2020);

  // Reduce region to get total water area
  // Use a coarse scale for reduceRegion to avoid memory issues, as we are summing areas.
  const scale = 1000; // meters

  const stats1987 = await pixelArea1987.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('area').getInfo();

  const stats2020 = await pixelArea2020.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('area').getInfo();

  // 4. Validation & Final Answer
  const waterArea1987_km2 = stats1987 ? stats1987 / 1e6 : null; // Convert m^2 to km^2
  const waterArea2020_km2 = stats2020 ? stats2020 / 1e6 : null;

  if (waterArea1987_km2 === null || waterArea2020_km2 === null) {
    console.log("C3"); // Calculation Failure if reduceRegion returns null
    return;
  }

  // Check for C2 (No Valid Pixels)
  if (waterArea1987_km2 === 0 && waterArea2020_km2 === 0) {
    console.log("Images exist, but after cloud masking/processing, 0 water pixels remain for both periods.");
    console.log("C2");
    return;
  }
  if (waterArea1987_km2 === 0) {
      console.log(`Warning: 0 water pixels for 1987. Area 1987: ${waterArea1987_km2.toFixed(2)} km^2.`);
  }
  if (waterArea2020_km2 === 0) {
      console.log(`Warning: 0 water pixels for 2020. Area 2020: ${waterArea2020_km2.toFixed(2)} km^2.`);
  }

  console.log(`1987 Images: ${size1987}`);
  console.log(`2020 Images: ${size2020}`);
  console.log(`Water area 1987 (April): ${waterArea1987_km2.toFixed(2)} km^2`);
  console.log(`Water area 2020 (April): ${waterArea2020_km2.toFixed(2)} km^2`);

  if (waterArea2020_km2 > waterArea1987_km2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
